function firmaElectronicaCtrl(n,t,i){"use strict";let u=JSON.parse(localStorage.getItem("accion"));if(u===null){location.href="/Home/Index";return}n.accion=u[0];let r="/FirmaElectronica/";n.firma={};n.fileSign={};n.entidades=[];n.firmas=[];n.tipoOperacion=0;n.openModal=function(t=null,i){if(n.tipoOperacion=i,i==1){$("#modalFirma").modal("show");return}i==2&&(n.firma=t,$("#modalUpdate").modal("show"))};n.initialLoad=function(){t.getData("get","/Entidad/OptionEntidad").then(function(t){n.entidades=t.data},n=>console.log(n));t.getData("get",r+"Get").then(function(t){if(t.id==0){i.toastr("warning",t.message,t.titleSms);return}n.firmas=t.data.map(n=>(n.contraseniaEncryp=n.contrasenia.replace(n.contrasenia,"*".repeat(n.contrasenia.length)),n))},n=>console.log(n))};n.initialLoad();n.contraseniaEncryp=function(n){n.contraseniaEncryp=n.contrasenia.replace(n.contrasenia,"*".repeat(n.contrasenia.length))};n.verContrasenia=function(n){n.contraseniaEncryp=n.contrasenia};n.post=function(){showLoader();let u=n.fileSign;if(u==null||u==undefined){hideLoader();i.toastr("warning","Por favor suba el archivo de la firma");return}if(!n.firma.contrasenia){hideLoader();i.toastr("warning","Por favor ingrese la contraseña");return}if(!n.firma.fechaCaducidad){hideLoader();i.toastr("warning","Por seleccione la fecha caducidad");return}t.getDataFile(r+"Post",u,n.firma).then(t=>{if(t.id==0){hideLoader();i.toastr("warning",t.message,t.titleSms);return}t.id==1&&(hideLoader(),i.toastr("success",t.message,t.titleSms),n.initialLoad(),$("#modalFirma").modal("hide"));hideLoader()},n=>console.log(n))};n.put=function(){t.getData("put",r+"Put",n.firma).then(function(t){if(t.id==0){i.toastr("warning",t.message,t.titleSms);return}t.id==1&&(i.toastr("success",t.message,t.titleSms),n.initialLoad(),$("#modalUpdate").modal("hide"))},n=>console.log(n))};n.askToDelete=function(t){Swal.fire({icon:"warning",text:"Esta seguro/a de eliminar esta firma electronica ahora?",showDenyButton:!0,confirmButtonText:`Si`,denyButtonText:`No`,allowOutsideClick:!1}).then(i=>{i.value&&n.delete(t)})};n.delete=function(n){t.getData("delete",r+"Delete?idFirmaElectronica="+n.idFirmaElectronica).then(n=>{if(n.id==0){i.toastr("warning",n.message,n.titleSms);return}n.id==1&&(i.toastr("success",n.message,n.titleSms),$("#modalFirma").modal("hide"))},n=>console.log(n))};$("#modalFirma, #modalUpdate").on("hide.bs.modal",()=>{n.firma={},n.fileSign={}})}app.controller("firmaElectronicaCtrl",firmaElectronicaCtrl);firmaElectronicaCtrl.$inject=["$scope","mainService","toastService"];